local _, WFJ = ...
WFJ.Data.add("quest", {
  [78088] = { "Uno strano artefatto", "Porta l'Althalaxx Orb a Delgren il Purificatore, all'⟦Maestra's Post=Accampamento di Maestra⟧, a ⟦Ashenvale=Valtetra⟧.", "<Il misterioso globo che tieni in mano ti riempie di un gelido terrore. Ti sembra quasi di sentire una voce echeggiare debolmente nella mente. Bassa e gutturale: capisci bene che la lingua parlata è di natura demoniaca.\n\nAnche per <un/una> paladin<o/a>, questa magia è fuori dalla tua portata. Trova qui a Kalimdor un paladino più esperto che possa aiutarti a capire la natura di questo sinistro oggetto.>", nil, nil, 0x54d84c8e, 0xf162540c, 0x00ddba1f, nil, nil, "...mm" },
  [78089] = { "Un consiglio da ⟦Stormwind=Roccavento⟧", "Porta l'Althalaxx Orb a ⟦Katherine the Pure=Katherine la Pura⟧, a ⟦Stormwind=Roccavento⟧.", "C'è un'oscurità potente in questo globo. La sua natura è chiaramente demoniaca, ma al di là di questo non sono in grado di capirne lo scopo.\n\nPorta il globo a colei che è nota come ⟦Katherine the Pure=Katherine la Pura⟧, nella Cattedrale di ⟦Stormwind=Roccavento⟧. Chiedile consiglio sul globo.", nil, nil, 0x5e36a76b, 0x3b4d2dbd, 0x789ee65c, nil, nil, "...mm" },
  [78090] = { "Un secondo parere", "Trova il santuario degli stregoni a ⟦Stormwind=Roccavento⟧ e chiedi consiglio sul globo.", "Non so bene cosa pensare di questo globo, {name}. Credo che ci servirà l'aiuto di... uno specialista.\n\nSappiamo che una setta di stregoni opera a ⟦Stormwind=Roccavento⟧. Ufficialmente respingiamo la presenza degli stregoni in città. Ufficiosamente, il loro sapere può tornare utile quando si ha a che fare con forze demoniache.\n\nTrova un rappresentante di questi stregoni e chiedigli un parere sul globo.", nil, nil, 0x87bb7435, 0x7c900333, 0x547fdd46, nil, nil, "...mm" },
  [78091] = { "Guadagnarsi il sale", "Raccogli 14 Summoner's Salt dai Blackrock Summoner nelle ⟦Redridge Mountains=Montagne Crestarossa⟧, poi torna da Ursula Deline a ⟦Stormwind=Roccavento⟧.", "Studierò il globo e ti dirò ciò che scoprirò, ma prima devi fare qualcosa per me.\n\nGli stregoni del clan ⟦Blackrock=Roccianera⟧ usano sali preparati appositamente per potenziare i loro rituali di evocazione. Prendine un po' dagli orchi di ⟦Redridge=Crestarossa⟧.\n\nAl tuo ritorno, condividerò con te i risultati dei miei studi.", nil, nil, 0x7d78a823, 0x1de3212f, 0xd4dd5884, nil, nil, "...mm" },
  [78092] = { "Va distrutto", "Raccogli 12 Motes of Mannoroth dai demoni di ⟦Ashenvale=Valtetra⟧. Portali, insieme all'Orb of Althalaxx, alla Spear of Mannoroth nel ⟦Demon Fall Canyon=Canyon della Caduta Infernale⟧.", "I tentacoli di coscienza che si protendono da questo globo sono troppo anche per uno stregone esperto come me: non riesco a resistervi a lungo. Mi costa ammetterlo, {name}, ma il globo va distrutto.\n\nIl globo è quasi indistruttibile, ma potrebbe essere vulnerabile all'arma di un potente signore dei demoni. Ho sentito dire che una lama del genere si trova a ⟦Ashenvale=Valtetra⟧, nel luogo in cui fu distrutto il signore degli abissi Mannoroth.\n\nRaccogli lì le particelle dell'essenza del demone caduto, poi frantuma il globo sulla lama.", nil, nil, 0x725d212a, 0x5fdc36a4, 0x72f2a6fa, nil, nil, "...mm" },
  [78093] = { "Ritorno da Delgren", "Riporta gli Orb Shards a Delgren.", "<I resti frantumati del globo giacciono ai tuoi piedi. Delgren vorrà vedere che ce l'hai fatta.>", nil, nil, 0x63f744cd, 0x47cd34b6, 0xc8898e87, nil, nil, "...mm" },
  [78124] = { nil, nil, nil, nil, nil, 0x3a40adb9, nil, nil, nil, nil, "emmmm" },
  [78127] = { nil, nil, nil, "Hai portato qualcosa da aggiungere alla nostra collezione?", "Grazie, {name}. Grazie ai tuoi sforzi il nostro sapere cresce.\n\nSe scopri altre opere magiche che potrebbero giovare alla biblioteca, portamele.", 0x3c34dd7c, nil, nil, 0x1400fbf0, 0xe184a784, "emm.." },
  [78132] = { nil, nil, nil, nil, nil, 0x979b839c, nil, nil, nil, nil, "emmmm" },
  [78133] = { nil, nil, nil, nil, nil, 0x0ad9d45d, nil, nil, nil, nil, "emmmm" },
  [78134] = { nil, nil, nil, nil, nil, 0xda427e86, nil, nil, nil, nil, "emmmm" },
  [78142] = { nil, nil, nil, "Hai portato qualcosa da aggiungere alla nostra collezione?", "Grazie, {name}. Grazie ai tuoi sforzi il nostro sapere cresce.\n\nSe scopri altre opere magiche che potrebbero giovare alla biblioteca, portamele.", 0x311bffcc, nil, nil, 0x1400fbf0, 0xe184a784, "emm.." },
  [78143] = { nil, nil, nil, "Hai portato qualcosa da aggiungere alla nostra collezione?", nil, 0x8a435740, nil, nil, 0x1400fbf0, nil, "emm.m" },
  [78145] = { nil, nil, nil, "Hai portato qualcosa da aggiungere alla nostra collezione?", "Grazie, {name}. Grazie ai tuoi sforzi il nostro sapere cresce.\n\nSe scopri altre opere magiche che potrebbero giovare alla biblioteca, portamele.", 0x309e1889, nil, nil, 0x1400fbf0, 0xe184a784, "emm.." },
  [78146] = { nil, nil, nil, nil, nil, 0xf3f22738, nil, nil, nil, nil, "emmmm" },
  [78147] = { nil, nil, nil, nil, nil, 0x8c93dda3, nil, nil, nil, nil, "emmmm" },
  [78148] = { nil, nil, nil, nil, nil, 0x7777a31c, nil, nil, nil, nil, "emmmm" },
  [78149] = { nil, nil, nil, "Hai portato qualcosa da aggiungere alla nostra collezione?", "Grazie, {name}. Grazie ai tuoi sforzi il nostro sapere cresce.\n\nSe scopri altre opere magiche che potrebbero giovare alla biblioteca, portamele.", 0x53dc86ff, nil, nil, 0x1400fbf0, 0xe184a784, "emm.." },
  [78150] = { "Amico della biblioteca", nil, nil, nil, nil, 0x9626da4d, nil, nil, nil, nil, ".mmmm" },
  [78261] = { nil, "Trova The Horn of Xelthos nel ⟦Shadowfang Keep=Forte di Zannascura⟧. Poi portalo al nascondiglio di C vicino a ⟦Pyrewood Village=Rovonero⟧. Devi portare a termine il lavoro da sol<o/a>.", "<Nel forziere c'è un biglietto>\n\nSalve, {name}.\n\nDesidero un tesoro noto come The Horn of Xelthos, che si trova da qualche parte nel ⟦Shadowfang Keep=Forte di Zannascura⟧.\n\nDi solito, per avventurarsi nel forte servono rinforzi. Per questo lavoro, però, la discrezione è della massima importanza.\n\nDevi andare da sol<o/a>.\n\nHo un contatto nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧, di nome Veenix. Dovrebbe poterti aiutare a superare il cancello del cortile. Il resto dipende da te.\n\nRiporta qui il corno e il tuo compenso ti verrà inviato poco dopo.\n\n- C", nil, nil, 0x8ef63440, 0xa04dc89a, 0x3eb0aa8f, nil, nil, "e..mm" },
  [78270] = { "Grimaldelli goblin", "Trova The Horn of Xelthos nel ⟦Shadowfang Keep=Forte di Zannascura⟧. Poi portalo al nascondiglio di C vicino a ⟦Pyrewood Village=Rovonero⟧.", "<Nel forziere c'è un biglietto>\n\nRieccoci, {name}.\n\nDesidero un tesoro noto come The Horn of Xelthos, che si trova da qualche parte nel ⟦Shadowfang Keep=Forte di Zannascura⟧.\n\nDi solito, per avventurarsi nel forte servono rinforzi. Per questo lavoro, però, la discrezione è della massima importanza.\n\nDevi andare da sol<o/a>.\n\nHo un contatto nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧, di nome Veenix. Dovrebbe poterti aiutare a superare il cancello del cortile. Il resto dipende da te.\n\nRiporta qui il corno e il tuo compenso ti verrà inviato poco dopo.\n\n- C", nil, nil, 0x6567783d, 0x8f719ff2, 0xe73ec883, nil, nil, "...mm" },
  [78307] = { nil, nil, nil, nil, nil, 0x8ef63440, nil, nil, nil, nil, "emmmm" },
  [78676] = { nil, "Trova The Eye of Bhossca nel ⟦Scarlet Monastery=Monastero Scarlatto⟧. Poi portalo al nascondiglio di C vicino a ⟦Pyrewood Village=Rovonero⟧. Devi portare a termine il lavoro da sol<o/a>.", "<Nel forziere c'è un biglietto>\n\nBentornat<o/a>, {name}.\n\nL'ultimo oggetto dei miei desideri è un artefatto noto come Eye of Bhossca. Le mie fonti dicono che l'occhio si trova da qualche parte nel ⟦Scarlet Monastery=Monastero Scarlatto⟧. Come per il ⟦Shadowfang Keep=Forte di Zannascura⟧, devi infiltrarti nel monastero da sol<o/a>.\n\nTi converrebbe trovare un travestimento prima di entrare: ti renderà un po' più facile muoverti. Sono sicuro che troverai qualcosa nei terreni del monastero.\n\nRiporta qui l'occhio e il compenso ti verrà consegnato come l'altra volta.\n\n- C", nil, nil, 0xdb721cea, 0x84b09c9a, 0xdef0af60, nil, nil, "e..mm" },
  [78699] = { nil, nil, nil, nil, nil, 0xdb721cea, nil, nil, nil, nil, "emmmm" },
  [78823] = { "Il terrore dei cieli del deserto", "Porta il Primitive Drawing a Hemet Nesingwary, nella Valle di Rovotorto.", "Il disegno è fatto di tratti grossolani e larghi e sembra raffigurare un grande uccello rapace. Nonostante la composizione semplice, l'artista guardava chiaramente questa creatura con paura e soggezione. Un esperto di caccia grossa potrebbe dirti di più.", nil, nil, 0x095389a7, 0xee6d5c93, 0x946d35b2, nil, nil, "...mm" },
  [78830] = { "Il terrore dei cieli del deserto", "Prendi una Crimson Trophy Quill da Gharrik nelle ⟦Badlands=Maleterre⟧. Poi torna da Hemet Nesingwary, nella Valle di Rovotorto.", "Questo disegno mi ricorda una storia che ho sentito durante un'altra spedizione, non molto tempo fa. Mi parlarono di un grande uccello, Gharrik, che regna sulle ⟦Badlands=Maleterre⟧ come predatore supremo.\n\nL'ultima volta è stata avvistata a nord-est del ⟦Camp Cagg=Campo Cagg⟧. Forse il suo nido è da qualche parte lì vicino?\n\nTi servirà un'esca viva per farla uscire allo scoperto. Ti presterò una gabbia per catturarne qualcuna. Nelle ⟦Badlands=Maleterre⟧ gli animaletti scarseggiano, quindi dovrai cercare l'esca altrove.\n\nUna penna di Gharrik sarebbe un bel trofeo. Di certo saresti sulla bocca di tutto l'accampamento.", nil, nil, 0x095389a7, 0x538655d8, 0x1ada8d6b, nil, nil, "...mm" },
  [78916] = { "Il cuore del Vuoto", "Porta la Blackfathom Pearl a Selgorm, vegliante dell'alba, a Darnassus.", "La temibile bestia Aku'mai giace morta. Nascosta tra le viscere e il sangue del suo cadavere gonfio c'è un'enorme perla iridescente, traboccante di pura energia del Vuoto.", nil, nil, 0xc885df05, 0x864e71af, 0x0a93b80a, nil, nil, "...mm" },
  [78917] = { "Il cuore del Vuoto", "Porta la Blackfathom Pearl a ⟦Bashana Runetotem=Bashana Totem Runico⟧, a ⟦Thunder Bluff=Picco del Tuono⟧.", "La temibile bestia Aku'mai giace morta. Nascosta tra le viscere e il sangue del suo cadavere gonfio c'è un'enorme perla iridescente, traboccante di pura energia del Vuoto.", nil, nil, 0xc885df05, 0x793b6e73, 0x0a93b80a, nil, nil, "...mm" },
})
